	var thick_in = float(mat.get_shader_parameter("line_thickness"))
	check("thick_entered", thick_in > 0.0, "Quando il giocatore entra in InteractionArea, line_thickness deve essere > 0.0 (trovato %s)" % str(thick_in))
	dummy_player.global_position = Vector2(9999, 9999)
	await wait_physics_frames(4)
	var thick_out = float(mat.get_shader_parameter("line_thickness"))
	check("thick_exited", thick_out == 0.0, "Quando il giocatore esce da InteractionArea, line_thickness deve tornare a 0.0 (trovato %s)" % str(thick_out))

